package com.order.order_service.controller;
import com.order.order_service.service.CheckoutService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size; import java.util.Map; import java.math.BigDecimal; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/orders") public class CheckoutController {private final CheckoutService service;public CheckoutController(CheckoutService s){service=s;}
 @PostMapping("/checkout") public Map<String,Object> checkout(@AuthenticationPrincipal Jwt jwt,@RequestHeader(value="Idempotency-Key",required=false) String key,@Valid @RequestBody Checkout request){long uid=Long.parseLong(jwt.getClaim("userId").toString());return service.checkout(uid,jwt.getSubject(),request.deliveryAddress(),key,jwt.getTokenValue(),request.couponCode(),request.latitude(),request.longitude(),request.customerPhone(),request.smsOptIn());}
 public record Checkout(@NotBlank @Size(max=500) String deliveryAddress,@Size(max=40) String couponCode,@jakarta.validation.constraints.DecimalMin("-90")@jakarta.validation.constraints.DecimalMax("90")BigDecimal latitude,@jakarta.validation.constraints.DecimalMin("-180")@jakarta.validation.constraints.DecimalMax("180")BigDecimal longitude,@Size(max=30) String customerPhone,boolean smsOptIn){}
}
